/**
 * WordprocessingML (.docx) writer and reader.
 *
 * A .docx is a ZIP whose `word/document.xml` carries the body. The writer
 * builds that package from the Markdown subset in `markdown.js`; the reader
 * walks the same body back into blocks so `office_read` can hand the model
 * Markdown instead of a wall of XML.
 *
 * Scope is deliberate: paragraphs, headings 1-3, bullet/numbered lists,
 * tables, inline bold/italic/code, fenced code and quotes. Images, charts,
 * headers/footers, comments and tracked changes are not produced and are
 * ignored on read (their text is still extracted where Word stores it in
 * `w:t`). That keeps the file valid and the implementation auditable; a
 * fidelity report is better than a silent half-conversion.
 */

import { Block, Run, parseMarkdown, runsToMarkdown, summarizeBlocks } from "./markdown.js";
import { OfficeError } from "./errors.js";
import { readZip, writeZip } from "./zip.js";

const NS_W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main";
const NS_R = "http://schemas.openxmlformats.org/officeDocument/2006/relationships";

/** Escape text for XML character data and attributes. */
export function escapeXml(text) {
	return String(text)
		.replace(/&/g, "&amp;")
		.replace(/</g, "&lt;")
		.replace(/>/g, "&gt;")
		.replace(/"/g, "&quot;")
		.replace(/'/g, "&apos;");
}

/** Decode the entity forms Word actually emits (named, decimal, hex). */
export function decodeXml(text) {
	return String(text).replace(/&(#x[0-9a-f]+|#\d+|amp|lt|gt|quot|apos);/gi, (match, entity) => {
		const lower = entity.toLowerCase();
		if (lower === "amp") return "&";
		if (lower === "lt") return "<";
		if (lower === "gt") return ">";
		if (lower === "quot") return '"';
		if (lower === "apos") return "'";
		if (lower.startsWith("#x")) return String.fromCodePoint(Number.parseInt(lower.slice(2), 16));
		return String.fromCodePoint(Number.parseInt(lower.slice(1), 10));
	});
}

/** `<w:t>` keeps leading/trailing spaces only when xml:space is set. */
function textRunXml(run) {
	if (run.text.length === 0) return "";
	const props = [];
	if (run.bold) props.push("<w:b/>");
	if (run.italic) props.push("<w:i/>");
	if (run.code) props.push('<w:rStyle w:val="CodeChar"/>');
	const rPr = props.length === 0 ? "" : `<w:rPr>${props.join("")}</w:rPr>`;
	return `<w:r>${rPr}<w:t xml:space="preserve">${escapeXml(run.text)}</w:t></w:r>`;
}

function paragraphXml(block, style, numbering) {
	const props = [];
	if (style !== undefined) props.push(`<w:pStyle w:val="${style}"/>`);
	if (numbering !== undefined) {
		props.push(`<w:numPr><w:ilvl w:val="${numbering.level}"/><w:numId w:val="${numbering.numId}"/></w:numPr>`);
	}
	if (block.quote) props.push('<w:ind w:left="420"/>');
	const pPr = props.length === 0 ? "" : `<w:pPr>${props.join("")}</w:pPr>`;
	const runs = block.runs.map(textRunXml).join("");
	return `<w:p>${pPr}${runs}</w:p>`;
}

function tableXml(block) {
	const columns = Math.max(1, ...block.rows.map((row) => row.length));
	const width = Math.floor(9638 / columns);
	const grid = `<w:tblGrid>${Array.from({ length: columns }, () => `<w:gridCol w:w="${width}"/>`).join("")}</w:tblGrid>`;
	const rows = block.rows.map((row, rowIndex) => {
		const cells = Array.from({ length: columns }, (_, column) => {
			const value = row[column] ?? "";
			const bold = rowIndex === 0 && block.rows.length > 1;
			const run = textRunXml(new Run(value, bold));
			return `<w:tc><w:tcPr><w:tcW w:w="${width}" w:type="dxa"/></w:tcPr><w:p>${run}</w:p></w:tc>`;
		}).join("");
		return `<w:tr>${cells}</w:tr>`;
	}).join("");
	return `<w:tbl><w:tblPr><w:tblStyle w:val="TableGrid"/><w:tblW w:type="pct" w:w="5000"/></w:tblPr>${grid}${rows}</w:tbl>`;
}

function documentXml(blocks) {
	const body = [];
	for (const block of blocks) {
		if (block.type === "heading") {
			body.push(paragraphXml(block, `Heading${block.level}`));
		} else if (block.type === "bullet") {
			body.push(paragraphXml(block, "ListParagraph", { level: block.level, numId: 1 }));
		} else if (block.type === "numbered") {
			body.push(paragraphXml(block, "ListParagraph", { level: block.level, numId: 2 }));
		} else if (block.type === "table") {
			body.push(tableXml(block));
			// Word needs a paragraph between two adjacent tables, otherwise they
			// merge into one table on open.
			body.push("<w:p/>");
		} else if (block.type === "code") {
			for (const line of block.lines.length === 0 ? [""] : block.lines) {
				const run = textRunXml(new Run(line.length === 0 ? " " : line, false, false, true));
				body.push(`<w:p><w:pPr><w:pStyle w:val="CodeBlock"/></w:pPr>${run}</w:p>`);
			}
		} else if (block.type === "rule") {
			body.push('<w:p><w:pPr><w:pBdr><w:bottom w:val="single" w:sz="6" w:space="1" w:color="D0D0D0"/></w:pBdr></w:pPr></w:p>');
		} else {
			body.push(paragraphXml(block, block.quote ? "Quote" : undefined));
		}
	}
	return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:document xmlns:w="${NS_W}" xmlns:r="${NS_R}"><w:body>${body.join("")}<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1134" w:right="1134" w:bottom="1134" w:left="1134" w:header="567" w:footer="567" w:gutter="0"/></w:sectPr></w:body></w:document>`;
}

